# ---------- helpers ---------------------------------------------------------
rss_lin <- function(y, t) {                     # closed-form RSS of y ~ t
  n <- length(y); if (n < 2) return(0)
  dt <- t - mean(t); dy <- y - mean(y)
  Sxx <- sum(dt * dt); if (Sxx <= 0) return(sum(dy * dy))
  sum(dy * dy) - sum(dt * dy)^2 / Sxx
}

interior <- function(n) {                        # candidate split indices
  lo <- max(MINSEG, floor(TRIM * n)); hi <- n - lo
  lo:hi
}

# --- M3: discontinuous level+trend break, K searched by min RSS -------------
fit_break <- function(y, t) {
  ks <- interior(length(y))
  r  <- sapply(ks, function(k) rss_lin(y[1:k], t[1:k]) +
                               rss_lin(y[(k+1):length(y)], t[(k+1):length(y)]))
  k  <- ks[which.min(r)]
  n  <- length(y)
  f1 <- lm(y[1:k] ~ t[1:k]); f2 <- lm(y[(k+1):n] ~ t[(k+1):n])
  fitted <- c(predict(f1), predict(f2))
  list(rss = min(r), k = 6L, split = k, fitted = fitted)
}

# --- M4: CONTINUOUS piecewise linear (a bend, not a jump), C searched -------
fit_segmented <- function(y, t) {
  cs <- t[interior(length(y))]
  best <- NULL
  for (C in cs) {
    m <- lm(y ~ t + I(pmax(t - C, 0)))
    r <- sum(resid(m)^2)
    if (is.null(best) || r < best$rss) best <- list(rss = r, C = C, fit = m)
  }
  list(rss = best$rss, k = 5L, knot = best$C, fitted = fitted(best$fit))
}

fit_gam <- function(y, t) {
  g <- gam(y ~ s(t, k = 10), method = "REML")
  list(rss = sum(resid(g)^2), k = sum(g$edf) + 1, fitted = fitted(g), obj = g)
}

# --- criteria ---------------------------------------------------------------
bic <- function(rss, n, k) n * log(rss / n) + k * log(n)
aic <- function(rss, n, k) n * log(rss / n) + 2 * k

# --- LOO-CV: the search happens INSIDE the fold -----------------------------
loo_rmse <- function(y, t, which_model) {
  n <- length(y); err <- numeric(n)
  for (i in seq_len(n)) {
    yi <- y[-i]; ti <- t[-i]
    p <- switch(which_model,
      flat      = mean(yi),
      linear    = { m <- lm(yi ~ ti);              predict(m, data.frame(ti = t[i])) },
      quadratic = { m <- lm(yi ~ ti + I(ti^2));    predict(m, data.frame(ti = t[i])) },
      break_lt  = {
        ks <- interior(length(yi))
        r  <- sapply(ks, function(k) rss_lin(yi[1:k], ti[1:k]) +
                                     rss_lin(yi[(k+1):length(yi)], ti[(k+1):length(yi)]))
        k  <- ks[which.min(r)]
        if (t[i] <= ti[k]) { m <- lm(yi[1:k] ~ ti[1:k]) } else {
          m <- lm(yi[(k+1):length(yi)] ~ ti[(k+1):length(yi)]) }
        as.numeric(coef(m)[1] + coef(m)[2] * t[i])
      },
      segmented = {
        cs <- ti[interior(length(yi))]; best <- NULL
        for (C in cs) { m <- lm(yi ~ ti + I(pmax(ti - C, 0))); r <- sum(resid(m)^2)
          if (is.null(best) || r < best$rss) best <- list(rss = r, C = C, fit = m) }
        as.numeric(predict(best$fit, data.frame(ti = t[i])))
      },
      spline    = { g <- gam(yi ~ s(ti, k = 10), method = "REML")
                    as.numeric(predict(g, data.frame(ti = t[i]))) })
    err[i] <- y[i] - p
  }
  sqrt(mean(err^2))
}

# --- AR(1)-error refit (does the preference survive serial correlation?) ----
ar1_bic <- function(y, t, which_model, split = NULL, knot = NULL) {
  df <- data.frame(y = y, t = t)
  f <- switch(which_model,
    flat      = y ~ 1,
    linear    = y ~ t,
    quadratic = y ~ t + I(t^2),
    break_lt  = { df$post <- as.integer(seq_along(y) > split); y ~ post * t },
    segmented = { df$seg <- pmax(t - knot, 0); y ~ t + seg },
    spline    = NULL)
  if (is.null(f)) return(NA_real_)
  m <- tryCatch(gls(f, data = df, correlation = corAR1(form = ~ t), method = "ML"),
                error = function(e) NULL)
  if (is.null(m)) return(NA_real_)
  as.numeric(BIC(m))
}

# ---------- run the race on one series --------------------------------------
race <- function(y, t, label, keep_fits = FALSE) {
  n <- length(y)
  m0 <- list(rss = sum((y - mean(y))^2), k = 2L, fitted = rep(mean(y), n))
  l1 <- lm(y ~ t);            m1 <- list(rss = sum(resid(l1)^2), k = 3L, fitted = fitted(l1))
  l2 <- lm(y ~ t + I(t^2));   m2 <- list(rss = sum(resid(l2)^2), k = 4L, fitted = fitted(l2))
  m3 <- fit_break(y, t)
  m4 <- fit_segmented(y, t)
  m5 <- fit_gam(y, t)

  ms   <- list(flat = m0, linear = m1, quadratic = m2,
               break_lt = m3, segmented = m4, spline = m5)
  keys <- names(ms)

  res <- data.frame(
    series = label,
    model  = keys,
    k      = sapply(ms, function(m) round(m$k, 2)),
    rss    = sapply(ms, function(m) m$rss),
    aic    = sapply(ms, function(m) aic(m$rss, n, m$k)),
    bic    = sapply(ms, function(m) bic(m$rss, n, m$k)),
    loo    = sapply(keys, function(kk) loo_rmse(y, t, kk)),
    ar1bic = sapply(keys, function(kk)
               ar1_bic(y, t, kk, split = m3$split, knot = m4$knot)),
    detail = c("", "", "",
               sprintf("break at %d", t[m3$split]),
               sprintf("knot at %d",  m4$knot),
               sprintf("edf %.2f", sum(m5$obj$edf))),
    stringsAsFactors = FALSE, row.names = NULL)

  res$dBIC <- round(res$bic - min(res$bic), 2)
  res$dAIC <- round(res$aic - min(res$aic), 2)
  res$dLOO <- round(res$loo - min(res$loo), 4)

  if (keep_fits) attr(res, "fits") <- ms
  res
}

# ============================== COMPOSITE ==================================
y <- d$PC1_index; t <- d$year
comp <- race(y, t, "PC1 composite (clean six)", keep_fits = TRUE)
fits <- attr(comp, "fits")

cat("\n================ HORSE RACE — CANONICAL PC1 ================\n")
print(comp[, c("model","k","rss","aic","bic","loo","ar1bic","detail","dBIC","dLOO")],
      row.names = FALSE, digits = 5)
cat(sprintf("\nBIC winner : %s\n", comp$model[which.min(comp$bic)]))
cat(sprintf("AIC winner : %s\n", comp$model[which.min(comp$aic)]))
cat(sprintf("LOO winner : %s\n", comp$model[which.min(comp$loo)]))
cat(sprintf("AR(1) BIC winner : %s\n",
            comp$model[which.min(replace(comp$ar1bic, is.na(comp$ar1bic), Inf))]))

# --- residual autocorrelation of the trend fit ------------------------------
r1 <- resid(lm(y ~ t))
cat(sprintf("\nAR(1) rho in linear-trend residuals: %.3f  (Box-Ljung p = %.3f)\n",
            as.numeric(acf(r1, plot = FALSE)$acf[2]),
            Box.test(r1, lag = 1, type = "Ljung-Box")$p.value))

# --- how much does the break buy over the bend? -----------------------------
cat(sprintf("\nRSS: linear %.2f -> segmented %.2f (%.1f%%) -> break %.2f (%.1f%%)\n",
            fits$linear$rss, fits$segmented$rss,
            100*(1 - fits$segmented$rss/fits$linear$rss),
            fits$break_lt$rss, 100*(1 - fits$break_lt$rss/fits$linear$rss)))

